-- Generated by Tools/generate_charleston_waves.py: Charleston's two-entrance, four-route finale.
-- Routes: 0 left/lower -> bottom; 1 top/upper -> right; 2 left/upper -> right; 3 top/central -> bottom.
-- Fifteen waves; first call is manual.
-- spawn_time is the nominal no-early-call schedule relative to wave 1.
-- Delay + countdown runs from the previous wave's actual start; early-call reward = 13.
-- Keep existing wave IDs because hero unlocks reference them.
DELETE FROM level_wave_enemy_spawn WHERE level_wave_id IN (SELECT id FROM level_wave WHERE level_info_id = '4ca73a47-98f6-41b6-815d-c2c797aa746e');

ON CONFLICT(id) DO UPDATE SET spawn_time=excluded.spawn_time, call_button_delay=excluded.call_button_delay, auto_start_countdown=excluded.auto_start_countdown, early_call_bonus=excluded.early_call_bonus;

DELETE FROM level_wave WHERE level_info_id = '4ca73a47-98f6-41b6-815d-c2c797aa746e' AND wave_index > 15;
UPDATE level_info SET num_waves = 15 WHERE id = '4ca73a47-98f6-41b6-815d-c2c797aa746e';

